2. //! See the [`atomic_with_ghost!`] documentation for more information.
3. #![allow(unused_imports)]
4. 
5. use super::atomic::*;
6. use super::invariant::*;
7. use super::modes::*;
8. use super::prelude::*;
9. 
10. verus! {
11. 
12. pub trait AtomicInvariantPredicate<K, V, G> {
13.     spec fn atomic_inv(k: K, v: V, g: G) -> bool;
14. }
15. 
16. } // verus!
17. macro_rules! declare_atomic_type {
18.     ($at_ident:ident, $patomic_ty:ident, $perm_ty:ty, $value_ty: ty, $atomic_pred_ty: ident) => {
19.         verus!{
20. 
